class Solution {
public:
    bool canReach(string s, int minJump, int maxJump) {
        int n = s.size();
        if (s[n - 1] == '1') return false;
        vector<char> dp(n, 0);
        dp[0] = 1;
        int pre = 0;
        for (int i = 1; i < n; i++) {
            if (i - minJump >= 0) pre += dp[i - minJump];
            if (i - maxJump - 1 >= 0) pre -= dp[i - maxJump - 1];
            if (s[i] == '0' && pre > 0) dp[i] = 1;
        }
        return dp[n - 1] == 1;
    }
};
